function solve(x){
  var c=x.config,e=x.event,s=x.state;
  if(s===null)s={v:c.initial,r:0,order:[],snaps:{},used:{}};
  var status;
  if(e.type==='write'){
    if(e.expect!==s.r)status='conflict';
    else{s.v=e.value;s.r++;status='written';}
  }else if(e.type==='save'){
    if(s.used[e.id])status='exists';
    else{
      s.used[e.id]=1;s.snaps[e.id]={value:s.v,revision:s.r};s.order.push(e.id);
      while(s.order.length>c.keep){var old=s.order.shift();delete s.snaps[old];}
      status='saved';
    }
  }else if(e.type==='rollback'){
    if(e.expect!==s.r)status='conflict';
    else if(!s.snaps[e.id])status='missing';
    else{s.v=s.snaps[e.id].value;s.r++;status='rolled_back';}
  }else if(e.type==='drop'){
    if(!s.snaps[e.id])status='missing';
    else{
      delete s.snaps[e.id];
      for(var i=0;i<s.order.length;i++)if(s.order[i]===e.id){s.order.splice(i,1);break;}
      status='dropped';
    }
  }
  var saved={};
  for(var j=0;j<s.order.length;j++){var id=s.order[j],q=s.snaps[id];saved[id]={value:q.value,revision:q.revision};}
  return {state:s,output:{status:status,value:s.v,revision:s.r,snapshots:s.order.slice(),saved:saved}};
}
